iqSampleButtons = (frames, label = "Select signal sample") =&gt; {
  let current = 0;
  const form = htl.html`&lt;div class="iq-frame-buttons" role="group" aria-label=${label}&gt;
    ${frames.map((_, i) =&gt; htl.html`&lt;button type="button" data-index=${i}&gt;Sample ${i + 1}&lt;/button&gt;`)}
  &lt;/div&gt;`;
  const setValue = (index, notify = true) =&gt; {
    current = index;
    for (const btn of form.querySelectorAll("button")) {
      btn.classList.toggle("active", +btn.dataset.index === current);
    }
    if (notify) form.dispatchEvent(new Event("input", { bubbles: true }));
  };
  Object.defineProperty(form, "value", {
    get: () =&gt; current,
    set: (index) =&gt; setValue(+index, false),
  });
  form.addEventListener("click", (event) =&gt; {
    const btn = event.target.closest("button");
    if (btn) setValue(+btn.dataset.index);
  });
  setValue(0, false);
  return form;
}
